"""Render review dossiers from computed offline artefacts. No prescription mutation."""
from pathlib import Path
import json,gzip,collections,re
R=Path('docs/det-engine/v11');E=R/'evidence/final'
blocks=json.load(gzip.open(E/'mesocycles.json.gz','rt'))
feedback=json.load(gzip.open(E/'feedback.json.gz','rt'))
old=json.load(gzip.open('docs/det-engine/v10/evidence/final/microcycles.json.gz','rt'))
selected=[b for b in blocks if b['model']=='separated_exposures']
def dump(name,content):
 content=re.sub(r'(\d)(min|jours|tests|séances|passages|échecs|inconnues|ignorés|todo|configurations|semaines)\b',r'\1 \2',content)
 (R/name).write_text(content+'\n')
def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','|'+'|'.join('---' for _ in headers)+'|']+['| '+' | '.join(str(c).replace('|','/') for c in row)+' |'for row in rows])
for b in selected:
 profile=b['profile'];v10=next(x for x in old if x['id']==profile);g=b['global'];diagnostic=v10['input']['diagnostic'];is_a='aerobic'in profile;name='MESOCYCLE_AEROBIC_PROFILE.md'if is_a else'MESOCYCLE_BALANCED_PROFILE.md'
 text=f'# Mésocycle candidat — {profile}\n\nStatut technique : {b["status"]}. Bloc de quatre semaines complet, **pas un plan Ironman complet**. Aucun avis expert ni adaptation réelle démontrée. Modèle retenu pour examen :separated_exposures ; compact_reference reste archivé comme comparaison, sans conclusion d’efficacité.\n\n'
 text+=f'Objectif Ironman, ambition finisher, niveau qualitatif trained, budget déclaré 600 min/semaine, mêmes six jours disponibles (mardi–dimanche), deux séances maximum/jour et au moins un jour de repos. Historique explicitement fictif : huit semaines à 600 min, enveloppes longues vélo {v10["input"]["longCaps"]["bike"]}/course {v10["input"]["longCaps"]["run"]}min. Ces enveloppes ne sont pas des mesures de tolérance.\n\n'
 text+=f'Limiteur présumé : {diagnostic["limiters"][0]["metric"]}, estimation synthétique {diagnostic["limiters"][0]["value"]}, confiance modèle {diagnostic["confidenceGlobal"]:.0%}. Incertitudes : '+ '; '.join(diagnostic['uncertainty']).rstrip('.')+'. Le focus '+v10['input']['focusSport']+' et les plafonds déjà documentés expliquent la répartition ; aucune fonction VLamax→dose ni prédiction de baisse n’est appliquée.\n\n'
 text+=table(['Semaine/type','Natation','Vélo','Course','Soutien','Total','Plafond natif','Plafond candidat','Reliquat candidat'],[[f'S{row["week"]}/{row["type"]}',row['totals']['swim'],row['totals']['bike'],row['totals']['run'],row['totals']['strength'],row['total'],w['context']['nativeBudget'],w['context']['budget'],w['context']['budget']-row['total']]for row,w in zip(g['rows'],b['weeks'])])
 text+='\n\nToutes les quantités ci-dessus sont en minutes prescrites. S2/S3 n’utilisent pas tout le plafond natif : aucun stimulus supplémentaire n’est justifié par des réponses futures encore inconnues. Le plafond candidat représente la politique de maintien de V10, augmentée uniquement si un plancher individuel natif l’exige. En S4, il applique aussi le plafond de récupération TFCL existant depuis la dernière charge effectivement programmée.\n'
 for w,row in zip(b['weeks'],g['rows']):
  c=w['context'];text+=f'\n## Semaine {c["week"]} — {c["weekType"]}, phase {c["phase"]}\n\n'
  text+=f'Position {c["mesocyclePosition"]}/4 ; compétition à {c["competitionDistanceDays"]}jours du début de semaine selon les dates synthétiques existantes. Décision :{w["decision"]["reason"]}.\n\n'
  text+=table(['Jour','Séances réellement calculées'],[[day,' ; '.join(f'{s.get("catalogId") or "Repos"} · {s.get("durationMin",0)}min'+(' · zones '+','.join(s.get('zones',[]))if not s.get('isRest')else'')for s in w['validation']['week']['sessions']if s['dayName']==day)]for day in ['lundi','mardi','mercredi','jeudi','vendredi','samedi','dimanche']])
  text+='\n\n'+table(['Rôle/source','Domaine doctrine','Min / retenu / max (min)','Justification de dose'],[[o['role']['sport']+'/'+o['role']['kind']+' · '+o['card']['id'],o['role']['domain'],f'{o["min"]}/{o["minutes"]}/{o["max"]}','Plancher réel et recette source sous enveloppe individuelle ; '+('Soutien du mouvement et mobilité ; aucune dose de force lourde démontrée' if o['role']['kind']=='skill' else 'Apprentissage de position aéro ; aucun crédit de longue autonome' if o['role']['kind']=='technical' else 'Socle d’endurance sous LT1 dans la discipline retenue ; hypothèse liée au limiteur, sans prédiction de changement métabolique')]for o in w['offers']])
  text+='\n\nLes longues autonomes et le travail de position sont comptés séparément. Le soutien est de la mobilité, sans équivalence force lourde. Les interactions sont gérées par le plafond total, les présences disciplinaires, l’espacement choisi, les jours sans dose et les récupérations écrites des fiches ; le coût réel cumulé et l’assimilation restent à observer. Les placements proches entre disciplines différentes ne démontrent pas leur innocuité individuelle.\n\n'
  text+=f'Contrôles hebdomadaires :{sum(x["status"]=="pass"for x in w["validation"]["checks"])}passages, {sum(x["status"]=="fail"for x in w["validation"]["checks"])}échecs, {len(w["validation"]["unknowns"])}inconnues ; erreurs bloquantes exécutées absentes :{w["validation"]["passesExecutedBlocking"]}.\n\n'
  text+='Inconnues :'+', '.join(w['validation']['unknowns'])+'. Les inconnues de chronologie concernent les sources dont seul l’intervalle numérique est structuré.\n\n'
  text+='Diagnostics natifs hebdomadaires conservés :\n\n'+ ('\n'.join('- '+x['severity']+' · '+x['code']+' : '+x['reason']for x in w['validation']['rawQuotas'])or'Aucun.')+'\n'
  if w['decision']['changes']:text+='\nChangements motivés :'+json.dumps(w['decision']['changes'],ensure_ascii=False)+'\n'
  if w['decision']['removedDevelopmentRoles']:text+='\nObligations de développement non reconduites en récupération selon le quota natif :'+', '.join(w['decision']['removedDevelopmentRoles'])+'. Aucune discipline supprimée.\n'
 text+='\n## Continuité, récupération et limites\n\n'
 text+=f'Audit technique de bloc :{b["technical"]["valid"]}. Contrôles globaux exécutés :{g["passesExecuted"]}. Pas de conflit d’espacement vélo/course aux frontières de semaines pour ce calendrier. Les plafonds et planchers existants restent actifs. La natation peut rester à son minimum en récupération ; une baisse dans chaque discipline n’est pas une loi physiologique.\n\n'
 text+='Le profil aérobie passe sa longue course70→75min en S3 uniquement pour respecter le plancher individualisé natif75, dans son enveloppe V10. Le profil équilibré maintient ses doses de développement. Ni maintien ni cinq minutes supplémentaires ne prouvent une adaptation obtenue. Le rythme trois semaines+une est une comparaison de cas, pas une prescription universelle.\n\n'
 text+=table(['Code historique brut','Sévérité','Nombre'],[[k[0],k[1],n]for k,n in collections.Counter((x['code'],x['severity'])for x in b['legacy']).items()])
 text+='\n\nLes erreurs sport_ratio et les avertissements de répétition/placement restent pertinents méthodologiquement ; ils ne sont pas effacés. Les diagnostics de course et couverture portent sur le préfixe de préparation16semaines. Voir [portées et limites](WEEK_SCOPE_VALIDATION.md). Aucun résultat candidat n’est présenté comme une conformité aux anciens validateurs. Toutes les sorties sont dans evidence/final/mesocycles.json.gz.\n\n'
 text+='Questions de revue : adéquation du couple longue+position en base ; précautions symptomatiques/posturales ; pertinence de la natation maintenue et des fréquences réduites en S4 ; future progression spécifique Ironman, nutrition et bricks ; acceptabilité du maintien/répétition pour les objectifs de ce profil. Les références et leurs limites restent [celles de V8](../v8/SCIENTIFIC_EVIDENCE_MATRIX.md).'
 dump(name,text)
text='# Feedback et progression entre semaines\n\nChaque observation est une fiction explicite, liée par empreinte au bloc de référence et à la prochaine séance. Aucun résultat n’est une adaptation observée. Le mécanisme de décision V9 reste réutilisé. Les modifications acceptées sont des propositions candidates, jamais des calendriers libérés automatiquement.\n\n'
text+=table(['Profil','Réponse synthétique','Décision','Modification S2'],[[r['profile'],x['case'],x['status'],f'{x["change"]["source"]} :{x["change"]["before"]}→{x["change"]["after"]}min'if x.get('change')else'Semaine retenue pour revue, aucune adaptation appliquée']for r in feedback for x in r['responses']])
text+='\n\nLa bonne assimilation et l’amélioration objective synthétique conservent les doses. L’amélioration simulée est un exemple de deux relevés submaximaux comparables (protocole fictif documenté dans responseEvidence) ; elle n’établit ni durabilité, ni réserve de charge supplémentaire, ni modification du limiteur.\n\nLa fatigue ressentie plus forte mais récupération déclarée complète autorise une recherche bornée parmi des doses déjà étayées : plafond ordinaire de course V10 ou plancher natif réel S2. Cela conduit à70→65min pour le profil aérobie et90→75min pour l’équilibré, même ID source. Les autres doses et placements restent inchangés. Les quatre semaines, les fenêtres globales, les quotas, les sources et l’absence de nouveaux diagnostics critiques **et avertissements** historiques sont revérifiés.\n\nLe premier essai équilibré 90→65min est conservé comme rejet : le retour S3 à90min ajoutait une alerte historique de progression. Le contrôle global a donc empêché qu’une réduction locale dégrade la suite. La nouvelle hypothèse75min vient du plafond ordinaire préinscrit, pas d’une recherche du seuil numérique de l’alerte. Les substitutions V9 rejetées ne sont pas répétées.\n\nLe seul passage de feedback testé est S1→S2 ; les autres transitions du bloc ne sont pas adaptées automatiquement. Douleur, test fiable contradictoire, données manquantes ou récupération incomplète sans douleur retiennent la prochaine prescription pour revue. Une réponse favorable ultérieure ne lève pas une suspension symptomatique : test de verrouillage dédié. Aucun diagnostic physiologique ni capacité n’est réécrit.\n\nPreuves :evidence/final/feedback.json.gz, feedback-summary.json ; rejet initial dans evidence/attempt-2. Sept réponses par profil, soit quatorze situations ; seules deux propositions réduisent réellement une dose, quatre maintiennent, huit retiennent la prescription. Ce décompte ne constitue pas un taux de guérison ou de validation sportive.'
dump('FEEDBACK_PROGRESSION.md',text)
dashboard={'version':'det-v11-1','recommendation':'NO-GO','distinctProfiles':2,'placementModels':2,'constructedCandidateBlocks':sum(b['status']=='constructed'for b in blocks),'distinctProfileBlocks':2,'weeksPerBlock':4,'trainingSessionsPerDistinctBlock':[sum(len(w['offers'])for w in b['weeks'])for b in selected],'expertReviewed':0,'historical600Altered':False,'historical600Regenerated':False,'legacyFullPreparationConforming':False,'rows':[{'profile':b['profile'],'model':b['model'],'status':b['status'],'weekMinutes':[r['total']for r in b['global']['rows']],'legacyBlocking':sum(x['severity']in['error','critical','blocking']for x in b['legacy']),'legacyWarnings':sum(x['severity']=='warning'for x in b['legacy']),'weeklyUnknowns':[w['validation']['unknowns']for w in b['weeks']]}for b in blocks]}
(R/'dashboard.json').write_text(json.dumps(dashboard,indent=2))
print(json.dumps({'reports':'computed dossiers written','profiles':2,'sessions':dashboard['trainingSessionsPerDistinctBlock']}))
# Consolidated results keep scientific attestation separate from execution success.
import re,hashlib
logs={'experimental':R/'evidence/final-delta/experimental.txt','historical':R/'evidence/validation/historical.txt','targeted':E/'tests.txt'}
summary={'version':'det-v11-1','types':{'exitCode':0,'proof':'evidence/final-delta/types.txt'},'node':{'passed':62,'proof':'evidence/validation/node.txt'},'experimental':{'passed':102,'skipped':43,'proof':str(logs['experimental'].relative_to(R))},'historical':{'passed':2999,'skipped':1,'todo':6,'proof':str(logs['historical'].relative_to(R))},'targeted':{'passed':17,'includedInExperimentalExceptThreeOptInEvidenceTests':True,'proof':str(logs['targeted'].relative_to(R))},'replay':json.loads((R/'evidence/reproducibility.json').read_text()),'notes':['do not sum targeted/replay with experimental as independent test coverage','historical suite inputs and all production sources unchanged after final missing-symptom correction','initial TypeScript failures, rejected candidates and environment interruption preserved']}
for name,log in logs.items():
 assert re.search(r'Tests\s+'+str(summary[name]['passed'])+r' passed',log.read_text()),(name,'test count mismatch')
assert summary['replay']['identical']
(R/'validation-summary.json').write_text(json.dumps(summary,indent=2))
text='# Résultats V11 — DRAFT / NO-GO\n\nDeux blocs de base de quatre semaines sont construits pour les deux profils synthétiques V10. Ils passent les contrôles bloquants hebdomadaires candidats exécutés, la sérialisation technique de bloc et les contrôles globaux exécutés. Ils conservent des avertissements historiques, des erreurs de ratios historiques et des inconnues de chronologie/fatigue. Aucun expert n’a validé ces prescriptions.\n\n'
text+=table(['Capacité','V10 conservée','V11 démontrée'],[['Portée','Deux microcycles Ironman, une semaine chacun','Deux blocs distincts de quatre semaines,26 séances chacun'],['Développement/récupération','Sans validation interhebdomadaire de bloc','Trois semaines de développement, une recovery calculée ; contrat candidat pour ces cas'],['Dosage','Priorités, minima et enveloppes synthétiques','Maintien sans hausse forcée ; seul plancher natif cause+5min de course en S3 du profil aérobie'],['Contexte source','Éligibilité générique et placement V6','Exclusion explicite récupération + placement source ; nouvelle offre vélo ciblée par le constructeur existant'],['Feedback','Réduction même ID sur microcycle','Sept réponses par profil, revalidation du bloc entier ; deux réductions admissibles, quatre maintiens, huit rétentions'],['Validation','Plan complet appliqué à une semaine, limites signalées','Adaptateur hebdomadaire explicite séparé, historique brut conservé parallèlement'],['Trail','Trois routes de dose inconnue','Trois inconnues confirmées ; aucune attestation ni nouvelle capacité inventée']])
text+='\n\n'+table(['Profil','S1','S2','S3','S4 récupération','Total bloc'],[[b['profile'],*[r['total']for r in b['global']['rows']],sum(r['total']for r in b['global']['rows'])]for b in selected])
text+='\n\nMinutes prescrites. Budget déclaré commun 600 min/semaine ; plafonds natifs 480,528,580,447min. Les plafonds candidats de développement sont volontairement plus bas lorsque rien ne justifie un supplément ; la récupération respecte aussi 70% de la dernière charge effectivement programmée (convention TFCL conservée). De ce plafond réduit, la semaine utilise 250 min et laisse encore du budget non utilisé. Une baisse n’est pas la preuve d’une récupération physiologique.\n\n'
text+='## Essais et corrections\n\n- Critère « baisse dans chaque discipline » rejeté comme généralisation nouvelle non étayée : la natation minimale peut être maintenue ; volume total et règles natives restent contrôlés.\n- Réduction équilibré 90→65min rejetée pour nouvelle alerte de progression S3 ; alternative 75 min issue du plafond ordinaire déjà documenté, validée sur tout le bloc.\n- Premier choix de récupération V3_BIKE_Z2_PROGRESSIF rejeté après lecture de avoid ; remplacement par A_BIKE_END_90_PRO existante,85min dans75–105, sans modification de fiche.\n- Champ douleur absent conservé inconnu, jamais converti automatiquement en false. Preuves avant correction et nouvelles preuves conservées ; décisions et doses identiques.\n- Deux placements comparés, deux profils distincts : quatre blocs candidats calculés représentent **deux** cas physiologiques, pas quatre athlètes. Le placement séparé est retenu pour dossier, sans supériorité sportive démontrée.\n\n'
text+='## Validation et couverture\n\nTypage final réussi ; 62 tests de gouvernance ; 102 tests expérimentaux réussis et 43 ignorés opt-in ; 2999 tests historiques réussis, 1 ignoré et 6 todo. 17 tests V11 ciblés réussissent aussi pendant la génération des preuves ; ils recouvrent les tests expérimentaux et trois tests opt-in de publication d’artefacts. Ils ne sont pas additionnés à la couverture comme tests indépendants.\n\nDeux processus indépendants produisent exactement les mêmes cinq artefacts (empreintes dans evidence/reproducibility.json). Un redémarrage d’environnement a interrompu la première validation après ses trois premières étapes ; seule la commande historique non achevée a été reprise. La dernière correction du champ douleur a été vérifiée par typage et suite expérimentale complète, les entrées historiques et sources de production restant inchangées. Les échecs de typage initiaux et rejets ne sont pas effacés.\n\n'
text+=table(['Lecture','Résultat et limite'],[['Technique','Deux blocs distincts complets et sérialisables ; pas de préparation de compétition entière'],['Hebdomadaire candidate','Aucun échec bloquant exécuté ; inconnues de fatigue, minutes internes et chronologie de certaines fiches'],['Globale candidate','Plafonds TFCL conservés, continuité des trois disciplines, récupération et transitions contrôlées ; pas de certificat de tolérance'],['Historique','Erreurs et avertissements bruts conservés ; pas de conformité complète historique revendiquée'],['Ratios','Fréquences et minutes distinctes ; quatre semaines ne couvrent pas la totalité du premier bloc de génération natif'],['Scientifique individuelle','Non démontrée : données et réponses synthétiques, pas d’adaptation observée ni dose optimale'],['Experte','Aucune revue indépendante effectuée'],['Historique600','Références préservées byte-à-byte ; pas de nouveau calcul des 600 configurations dans cette mission V11'],['Autres objectifs','Non-régression logicielle multiobjectifs existante ; aucun nouveau bloc sportif d’une autre famille démontré en V11']])
text+='\n\nLes ratios historiques et répétitions ne sont pas tous des erreurs hors contexte : leur portée méthodologique reste à discuter. Les dossiers publient les nombres et diagnostics bruts par profil ; ils ne les masquent pas dans un score agrégé. Aucun HIT hebdomadaire n’est ajouté pour satisfaire une étiquette historique.\n\n'
text+='## Décisions humaines réellement nécessaires avant promotion\n\n1. Revue sportive indépendante du couple longue+position et des deux blocs de base, des précautions posturales/symptomatiques et de la récupération avec natation minimale maintenue ; les variantes restent candidates.\n2. Preuves de parcours et réponse musculaire individuelles pour les trois sources trail inconnues avant toute attestation verticale ; absence de D− jamais assimilée à zéro.\n3. Avant extension spécifique Ironman : données de réponse suffisantes et objectifs de nutrition/longues/bricks explicités, puis revue de la préparation entière. La V11 ne démontre pas cette capacité ultérieure.\n\nAucune décision de production n’est demandée. Aucune fusion, publication Lovable, migration, dépense, écriture Nolio/athlète, modification du moteur actuel ou des validateurs historiques. PR420 reste en brouillon, NO-GO. Le registre de dix unités s’arrête à sa clôture ou au délai absolu ; aucune continuation permanente n’est prétendue.\n\nLes huit livrables sont indexés dans [README](README.md). Provenance, scripts, versions et état de reprise sont conservés dans le même dossier.'
dump('V11_RESULTS.md',text)
